/* ===================== PAINEL DO PROFESSOR ===================== */
const ADM=[['ov','Visão geral','home'],['stu','Estudantes','users'],['mods','Módulos','book'],['acts','Atividades','clip'],['games','Minigames','game'],['sims','Simulações','compass'],['ach','Conquistas','medal'],['rank','Ranking','trophy'],['pres','Avaliações presenciais','check'],['rep','Relatórios','chart'],['acc','Contas','shield'],['set','Configurações','gear']];
const val=id=>{const e=document.getElementById(id);return e?e.value:''};
const lines=id=>String(val(id)).split('\n').map(s=>s.trim()).filter(Boolean);
const fld=(l,id,v,o)=>{o=o||{};return '<label class="f">'+l+(o.h?'<span class="h">'+o.h+'</span>':'')+(o.ta?'<textarea id="'+id+'" rows="'+(o.rows||3)+'" placeholder="'+esc(o.ph||'')+'">'+esc(v)+'</textarea>':'<input type="'+(o.type||'text')+'" id="'+id+'" value="'+esc(v)+'" placeholder="'+esc(o.ph||'')+'" '+(o.min!=null?'min="'+o.min+'"':'')+(o.max!=null?' max="'+o.max+'"':'')+'>')+'</label>'};
const sel=(id,opts,v)=>'<select id="'+id+'">'+opts.map(([k,n])=>'<option value="'+esc(k)+'" '+(String(k)===String(v)?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select>';
const tNick=u=>{const t=S.raw.teachers[u];return t?t.nick:'Professor'};
function students(){const ids=new Set([...Object.keys(S.raw.public),...Object.keys(S.raw.priv)]);return [...ids].map(u=>{const pub=S.raw.public[u]||{},p=S.raw.priv[u]?normPriv(clone(S.raw.priv[u])):null,g=S.raw.grades[u]||{};return{u,pub,p,g,nick:(p&&p.nick)||pub.nick||'(sem apelido)',full:p&&p.full||'',T:sum(pub.pts)+sum(pub.adj)}}).sort((a,b)=>a.nick.localeCompare(b.nick))}
function stuInfo(s){const p=s.p||normPriv({});const cr=criteria(p);return Object.assign({cr,essay:countEssayPend(p,s.g),last:Math.max(+p.hist&&0||0,(s.pub&&s.pub.upd)||0,...Object.values(p.acts).map(a=>a.at||0)),lv:lvlOf(s.T).L},{})}
function modPctOf(m,p){const mp=p.mods[m.id]||{r:{}};if(mp.done)return 100;const secs=(m.sections||[]).length;const rd=(m.sections||[]).filter(s=>mp.r&&mp.r[s.id]).length;const act=S.acts.find(a=>a.mod===m.id&&a.kind==='activity'&&a.st==='published'),ass=S.acts.find(a=>a.mod===m.id&&a.kind==='assessment'&&a.st==='published');const tot=secs+(act?1:0)+(ass?1:0);const d=rd+(act&&p.acts[act.id]&&p.acts[act.id].n>0?1:0)+(ass&&p.acts[ass.id]&&p.acts[ass.id].best>=S.cfg.modPass?1:0);return tot?Math.round(100*d/tot):0}
function modPct(m){return modPctOf(m,S.priv)}
async function saveState(patch){await DB.upd('cfg/state',patch)}
async function saveCfg(patch){await DB.upd('cfg/main',patch)}
function guard(fn){return async(...a)=>{try{await fn(...a)}catch(e){console.error(e);toast('Ação não concluída: '+(e.code||e.message)+'. Você precisa de permissão de editor.','err',5000)}}}

function adminShell(){
 const ADMV=ADM;
 const nav=ADMV.map(([v,n,i])=>'<button class="'+(S.aview===v?'on':'')+'" data-act="ago" data-v="'+v+'">'+ic(i)+n+'</button>').join('');
 const tabs=ADMV.map(([v,n,i])=>'<button class="'+(S.aview===v?'on':'')+'" data-act="ago" data-v="'+v+'">'+ic(i)+n+'</button>').join('');
 const V={ov:aOv,stu:aStu,mods:aMods,acts:aActs,games:aGames,sims:aSims,ach:aAch,rank:aRank,pres:aPres,rep:aRep,set:aSet,acc:aAcc};if(!V[S.aview])S.aview='ov';
 return '<div class="app"><aside class="side"><div class="brand"><div class="logo">'+ic('cross')+'</div><div>Soldados Socorristas<small>PAINEL DO PROFESSOR</small></div></div>'+nav+'<div class="sp"></div><button data-act="theme">'+ic('sun')+'Tema claro/escuro</button><button data-act="tomode" data-m="student">'+ic('eye')+'Ver como estudante</button><button data-act="logout">'+ic('lock')+'Sair</button></aside>'+
 '<main class="main"><div class="wrap"><div class="topbar"><div class="brand"><div class="logo">'+ic('cross')+'</div><div>Painel do professor<small>'+esc(tNick(S.uid))+'</small></div></div><div class="row"><button class="btn sm sec" data-act="theme">'+ic('sun')+'</button><button class="btn sm nav" data-act="tomode" data-m="student">'+ic('eye')+' Ver como aluno</button><button class="btn sm sec" data-act="logout">Sair</button></div></div>'+
 '<div class="atabs m">'+tabs+'</div>'+V[S.aview]()+'</div></main></div>'}
function hdr(t,sub,btn){return '<div class="row sb"><div><h1>'+t+'</h1>'+(sub?'<p class="mut" style="margin:4px 0 0">'+sub+'</p>':'')+'</div>'+(btn||'')+'</div>'}
function empty(t,i){return '<div class="card empty">'+ic(i||'info')+'<p>'+t+'</p></div>'}

/* ---------- Visão geral ---------- */
function aOv(){const st=students();const pm=S.mods.filter(m=>m.st==='published');const info=st.map(s=>Object.assign({s},stuInfo(s)));
 const ess=info.reduce((a,x)=>a+x.essay,0);const prog=st.length?Math.round(info.reduce((a,x)=>a+pct(x.cr.done,x.cr.total),0)/st.length):0;const avg=st.length?Math.round(info.reduce((a,x)=>a+x.cr.c2,0)/st.length):0;const okb=info.filter(x=>x.cr.ok1&&x.cr.ok2);
 const rec=[];st.forEach(s=>{if(s.p)s.p.hist.slice(0,5).forEach(h=>rec.push({n:s.nick,h}))});rec.sort((a,b)=>b.h.t-a.h.t);
 const drafts=S.acts.filter(a=>a.st!=='published').length+S.sims.filter(a=>a.st!=='published').length;
 return hdr('Visão geral','Acompanhe a turma em um relance.')+
 '<div class="grid g4"><div class="card stat">'+ico('t','users')+'<div><b>'+st.length+'</b><span class="xs mut">estudantes</span></div></div><div class="card stat">'+ico('b','book')+'<div><b>'+pm.length+'/'+S.mods.length+'</b><span class="xs mut">módulos publicados</span></div></div><div class="card stat">'+ico('o','clip')+'<div><b>'+ess+'</b><span class="xs mut">discursivas a corrigir</span></div></div><div class="card stat">'+ico('g','chart')+'<div><b>'+prog+'%</b><span class="xs mut">progresso geral</span></div></div><div class="card stat">'+ico('p','star')+'<div><b>'+avg+'%</b><span class="xs mut">média nas avaliações</span></div></div><div class="card stat">'+ico('y','shield')+'<div><b>'+okb.length+'</b><span class="xs mut">atingiram os 2 critérios</span></div></div><div class="card stat">'+ico('r','alert')+'<div><b>'+drafts+'</b><span class="xs mut">rascunhos/não publicados</span></div></div></div>'+
 (ess?'<div class="notice">'+ic('clock')+'<div><b>'+ess+' resposta(s) discursiva(s)</b> aguardam sua correção. <button class="btn sm" data-act="ago" data-v="acts" data-p=\'{"tab":"ess"}\'>Corrigir agora</button></div></div>':'')+
 '<div class="grid g2"><div class="card col"><h3>Resultados recentes</h3>'+(rec.length?rec.slice(0,8).map(r=>'<div class="row sb" style="flex-wrap:nowrap"><div class="grow"><b class="sm">'+esc(r.n)+'</b><div class="xs mut">'+esc(r.h.x)+' · '+fdt(r.h.t)+'</div></div><span class="chip p">+'+r.h.p+'</span></div>').join(''):'<p class="mut sm">Sem atividade registrada ainda.</p>')+'</div>'+
 '<div class="card col"><h3>Concluíram os critérios</h3>'+(okb.length?okb.map(x=>'<div class="row"><span class="chip g">'+ic('check')+'</span><b>'+esc(x.s.nick)+'</b><span class="xs mut">'+x.cr.c1+'% / '+x.cr.c2+'%</span></div>').join(''):'<p class="mut sm">Ninguém atingiu os dois critérios ainda ('+S.cfg.crit1+'% objetivos · '+S.cfg.crit2+'% avaliações).</p>')+'<p class="xs mut">Aprovação digital ≠ certificação prática. Registre a avaliação presencial na aba própria.</p></div></div>'+
 (st.length?'':'<div class="card empty">'+ic('users')+'<p>Nenhum estudante cadastrado ainda. Cadastre os alunos na aba <b>Contas</b> e entregue o usuário e a senha inicial a cada um.</p></div>')}

/* ---------- Estudantes ---------- */
function aStu(){if(S.ap.id)return aStuDet();const q=norm(S.ap.q||'');const st=students().filter(s=>!q||norm(s.nick+' '+s.full).includes(q));
 const orph=Object.keys(S.raw.grades).filter(u=>!S.raw.public[u]&&!S.raw.priv[u]);
 return hdr('Estudantes',students().length+' cadastrados')+'<div class="row"><input type="text" id="st-q" placeholder="Buscar por apelido ou nome…" value="'+esc(S.ap.q||'')+'" style="max-width:320px"><button class="btn sec" data-act="st-search">'+ic('search')+' Buscar</button></div>'+
 (st.length?'<div class="tbl"><table><thead><tr><th>Estudante</th><th>Nível</th><th>Pontos</th><th>Módulos</th><th>Critério 1</th><th>Critério 2</th><th></th></tr></thead><tbody>'+st.map(s=>{const i=stuInfo(s);return '<tr><td><div class="row" style="flex-wrap:nowrap"><div style="width:34px;border-radius:50%;overflow:hidden;line-height:0;flex:none">'+avatarSvg(s.pub.av||s.p&&s.p.av)+'</div><div><b>'+esc(s.nick)+'</b><div class="xs mut">'+esc(s.full)+'</div></div></div></td><td>'+i.lv+'</td><td>'+s.T+'</td><td>'+i.cr.done+'/'+i.cr.total+'</td><td><span class="chip '+(i.cr.ok1?'g':'')+'">'+i.cr.c1+'%</span></td><td><span class="chip '+(i.cr.ok2?'g':'')+'">'+i.cr.c2+'%</span></td><td><div class="row" style="flex-wrap:nowrap"><button class="btn sm sec" data-act="ago" data-v="stu" data-p=\'{"id":"'+esc(s.u)+'"}\'>Abrir</button><button class="btn sm danger" data-act="stu-del" data-u="'+esc(s.u)+'" aria-label="Excluir aluno">'+ic('trash')+'</button></div></td></tr>'}).join('')+'</tbody></table></div>':empty('Nenhum estudante encontrado.','users'))+
 (orph.length?'<div class="card col"><h3>Registros de professor sem conta de aluno</h3><p class="sm mut">Alunos que excluíram a conta deixam aqui correções e avaliações presenciais. Você pode remover.</p>'+orph.map(u=>'<div class="row sb"><span class="sm">Registro '+esc(u.slice(0,6))+'… · '+((S.raw.grades[u].pres||[]).length)+' presencial(is) · '+Object.keys(S.raw.grades[u].es||{}).length+' correção(ões)</span><button class="btn sm danger" data-act="stu-del" data-u="'+esc(u)+'">'+ic('trash')+' Remover registro</button></div>').join('')+'</div>':'')}
ACT['st-search']=()=>{S.ap={q:val('st-q')};render()};
function aStuDet(){const u=S.ap.id;const s=students().find(x=>x.u===u);if(!s)return '<button class="btn ghost" data-act="ago" data-v="stu">'+ic('left')+' Estudantes</button>'+empty('Estudante não encontrado.');const p=s.p||normPriv({}),cr=criteria(p),L=lvlOf(s.T);const g=s.g;
 const pm=S.mods.filter(m=>m.st!=='draft');
 return '<button class="btn ghost" data-act="ago" data-v="stu">'+ic('left')+' Estudantes</button>'+
 '<div class="hero"><div class="av">'+avatarSvg(s.pub.av||p.av)+'</div><div class="grow col" style="gap:6px"><h1>'+esc(s.nick)+'</h1><div class="mut sm">'+(s.full?esc(s.full)+' · ':'')+'desde '+fdate(p.created||s.pub.since)+'</div><div class="row"><span class="chip y">Nível '+L.L+' · '+L.name+'</span><span class="chip p">'+s.T+' pontos</span><span class="chip">'+Object.keys(p.ach).length+' conquistas</span></div></div></div>'+
 '<div class="grid g2"><div class="card col"><h3>Critérios de conclusão</h3>'+critBars(cr)+'<div class="row"><span class="chip '+(cr.ok1?'g':'r')+'">Critério 1: '+(cr.ok1?'atingido':'não atingido')+'</span><span class="chip '+(cr.ok2?'g':'r')+'">Critério 2: '+(cr.ok2?'atingido':'não atingido')+'</span></div></div>'+
 '<div class="card col"><h3>Corrigir pontuação</h3><p class="xs mut" style="margin:0">Ajustes ficam registrados no histórico. Use valores negativos para remover pontos.</p><div class="row"><input type="number" id="adj-n" placeholder="± pontos" style="max-width:130px"><input type="text" id="adj-r" placeholder="Motivo" class="grow"></div><button class="btn" data-act="adj-go" data-u="'+esc(u)+'">Aplicar ajuste</button>'+((g.adjLog||[]).length?'<div class="hr"></div>'+g.adjLog.slice().reverse().slice(0,5).map(a=>'<div class="xs"><b>'+(a.pts>0?'+':'')+a.pts+'</b> · '+esc(a.reason)+' · '+fdt(a.t)+' · '+esc(a.by)+'</div>').join(''):'')+'</div></div>'+
 '<div class="card col"><h3>Módulos</h3>'+pm.map(m=>'<div class="row sb"><span class="sm">'+(m.n||m.ord)+'. '+esc(m.title)+'</span><div class="row" style="gap:6px"><div class="bar" style="width:90px"><i style="width:'+modPctOf(m,p)+'%"></i></div><span class="chip '+(p.mods[m.id]&&p.mods[m.id].done?'g':'')+'">'+modPctOf(m,p)+'%</span></div></div>').join('')+'</div>'+
 '<div class="card col"><h3>Atividades e notas</h3>'+(Object.keys(p.acts).length?'<div class="tbl"><table><thead><tr><th>Atividade</th><th>Melhor</th><th>Tent.</th><th></th></tr></thead><tbody>'+Object.entries(p.acts).map(([i,r])=>{const a=S.acts.find(x=>x.id===i);return '<tr><td>'+esc(a?a.title:i)+'</td><td><span class="chip '+(r.best>=90?'g':r.best>=60?'y':'r')+'">'+r.best+'%</span></td><td>'+r.n+'</td><td><button class="btn sm sec" data-act="ans-view" data-u="'+esc(u)+'" data-a="'+esc(i)+'">Ver respostas</button></td></tr>'}).join('')+'</tbody></table></div>':'<p class="mut sm">Nenhuma atividade feita.</p>')+'</div>'+
 '<div class="card col"><h3>Simulações</h3>'+(Object.keys(p.sims).length?Object.entries(p.sims).map(([i,r])=>{const sm=S.sims.find(x=>x.id===i);return '<div class="row sb"><span class="sm">'+esc(sm?sm.title:i)+'</span><span class="chip '+(r.best>=90?'g':r.best>=60?'y':'r')+'">Melhor '+r.best+'% · '+r.n+'x · últ. decisões: '+((r.last&&r.last.path)||[]).map(q=>q==='best'?'●':q==='ok'?'◐':'○').join('')+'</span></div>'}).join(''):'<p class="mut sm">Nenhuma simulação.</p>')+'</div>'+
 '<div class="card col"><h3>Histórico</h3>'+(p.hist.length?p.hist.slice(0,15).map(h=>'<div class="row sb"><span class="sm">'+esc(h.x)+' <span class="xs mut">'+fdt(h.t)+'</span></span><span class="chip p">+'+h.p+'</span></div>').join(''):'<p class="mut sm">Vazio.</p>')+'</div>'+
 '<div class="card col" style="border:2px solid var(--red)"><h3 style="color:var(--red)">Excluir conta do aluno</h3><p class="sm mut" style="margin:0">Apaga perfil, progresso, pontos, conquistas e registros do professor deste aluno. Não pode ser desfeito.</p><button class="btn danger" data-act="stu-del" data-u="'+esc(u)+'" data-back="1">'+ic('trash')+' Excluir este aluno</button></div>'}
ACT['adj-go']=guard(async t=>{const u=t.dataset.u,n=parseInt(val('adj-n'),10),r=val('adj-r').trim();if(!n||!r){toast('Informe os pontos e o motivo.','err');return}
 const pub=S.raw.public[u]||{};const d=dk();const cur=(pub.adj&&pub.adj[d])||0;await DB.upd('public/'+u,{adj:{[d]:cur+n}});
 const g=S.raw.grades[u]||{};await DB.upd('grades/'+u,{adjLog:(g.adjLog||[]).concat([{t:now(),pts:n,reason:r,by:tNick(S.uid)}]).slice(-60)});toast('Ajuste aplicado.','ok')});
ACT['ans-view']=t=>{const u=t.dataset.u,a=S.acts.find(x=>x.id===t.dataset.a);const p=S.raw.priv[u],rec=p&&p.acts&&p.acts[t.dataset.a];if(!a||!rec||!rec.last){toast('Sem respostas.','err');return}
 const g=S.raw.grades[u]||{};openModal('<h3>'+esc(a.title)+'</h3><p class="xs mut">Última tentativa: '+fdt(rec.last.at)+' · '+rec.last.pct+'%</p><div class="col">'+(a.questions||[]).map(q=>{const v=rec.last.ans[q.id],r=rec.last.r[q.id];const gg=g.es&&g.es[q.id];return '<div class="card flat"><div class="b sm">'+esc(q.q)+'</div><div class="sm"><b>Resposta:</b> '+esc(v===undefined?'—':ansText(q,v))+'</div>'+(q.type==='essay'?(gg?'<div class="chip g">Nota '+gg.s+'/'+gg.m+'</div>':'<div class="chip y">Sem correção</div>'):'<span class="chip '+(r===1?'g':r>0?'y':'r')+'">'+(r===1?'Certa':r>0?'Parcial':'Errada')+'</span>')+'</div>'}).join('')+'</div><div class="row" style="justify-content:flex-end;margin-top:12px"><button class="btn" data-act="mclose">Fechar</button></div>')};
ACT['stu-del']=t=>{const u=t.dataset.u;const s=students().find(x=>x.u===u);confirmBox('Excluir conta do aluno?','Você vai apagar <b>'+esc(s?s.nick:'este registro')+'</b>: perfil, progresso, pontos, conquistas, avatar, posição no ranking e registros de professor (correções e avaliações presenciais). Esta ação não pode ser desfeita.','stu-del2',{u:u,back:t.dataset.back||''},'Excluir definitivamente')};
ACT['stu-del2']=guard(async t=>{const u=t.dataset.u;closeModal();await DB.api('DELETE','/users/'+u);DB.cache.public&&delete DB.cache.public[u];if(S.ap.id===u)S.ap={};S.users=null;toast('Conta do aluno excluída.','ok');render()});

/* ---------- Módulos ---------- */
const STN={published:'Publicado',locked:'Bloqueado',draft:'Rascunho'};
function aMods(){if(S.ap.edit)return aModEd();const st=students();
 return hdr('Módulos','Publique, bloqueie, reordene e edite os conteúdos.','<div class="row"><button class="btn" data-act="mod-new">'+ic('plus')+' Novo módulo</button></div>')+
 '<div class="card row sb"><label class="row" style="gap:8px"><input type="checkbox" id="seq" '+(S.cfg.sequential?'checked':'')+' data-act="seq-tog" style="width:20px;height:20px"><span class="b sm">Liberar progressivamente (o aluno só abre o próximo módulo depois de concluir o anterior)</span></label><div class="row"><button class="btn sm sec" data-act="mods-all" data-st="published">Publicar todos</button><button class="btn sm sec" data-act="mods-all" data-st="locked">Bloquear todos</button></div></div>'+
 '<div class="col">'+S.mods.map((m,i)=>{const dn=st.filter(s=>s.p&&s.p.mods[m.id]&&s.p.mods[m.id].done).length;return '<div class="card"><div class="row sb"><div class="row" style="flex-wrap:nowrap">'+modIco(m)+'<div><div class="b">'+(i+1)+'. '+esc(m.title)+(m._ov?' <span class="chip y">editado</span>':'')+(m._def?'':' <span class="chip t">criado por você</span>')+'</div><div class="xs mut">'+(m.sections||[]).length+' seções · '+dn+'/'+st.length+' alunos concluíram</div></div></div><div class="row"><select data-chg="mod-st" data-id="'+m.id+'" style="width:auto">'+Object.entries(STN).map(([k,n])=>'<option value="'+k+'" '+(m.st===k?'selected':'')+'>'+n+'</option>').join('')+'</select><button class="btn sm sec" data-act="mod-mv" data-id="'+m.id+'" data-d="-1" '+(i===0?'disabled':'')+' aria-label="Subir">'+ic('up')+'</button><button class="btn sm sec" data-act="mod-mv" data-id="'+m.id+'" data-d="1" '+(i===S.mods.length-1?'disabled':'')+' aria-label="Descer">'+ic('down')+'</button><button class="btn sm" data-act="mod-ed" data-id="'+m.id+'">'+ic('edit')+' Editar</button>'+((m._ov||!m._def)?'<button class="btn sm danger" data-act="mod-del" data-id="'+m.id+'" aria-label="'+(m._def?'Restaurar padrão':'Excluir')+'">'+ic('trash')+'</button>':'')+'</div></div></div>'}).join('')+'</div>'}
document.addEventListener('change',guard(async e=>{const t=e.target;if(t.dataset&&t.dataset.chg==='mod-st'){await saveState({mods:{[t.dataset.id]:{st:t.value}}});toast('Módulo: '+STN[t.value],'ok',1500)}
 if(t.dataset&&t.dataset.chg==='act-st'){await saveState({acts:{[t.dataset.id]:{st:t.value}}});toast('Atividade: '+(t.value==='published'?'publicada':'rascunho'),'ok',1500)}
 if(t.dataset&&t.dataset.chg==='sim-st'){await saveState({sims:{[t.dataset.id]:{st:t.value}}});toast('Simulação: '+(t.value==='published'?'publicada':'rascunho'),'ok',1500)}
 if(t.dataset&&t.dataset.chg==='ach-st'){await saveState({ach:{[t.dataset.id]:{st:t.value}}})}
 if(t.id==='qe-file'&&t.files&&t.files[0]){const url=await resizeImg(t.files[0],640);S.qimg=url;const pv=$('#qe-prev');if(pv)pv.innerHTML='<img src="'+url+'" alt="Pré-visualização" style="max-height:140px;border-radius:10px">'}}));
ACT['seq-tog']=guard(async t=>{await saveCfg({sequential:t.checked});toast('Preferência salva.','ok',1500)});
ACT['mods-all']=guard(async t=>{const p={};S.mods.forEach(m=>p[m.id]={st:t.dataset.st});await saveState({mods:p});toast('Atualizado.','ok')});
ACT['mod-mv']=guard(async t=>{const i=S.mods.findIndex(m=>m.id===t.dataset.id),j=i+(+t.dataset.d);if(j<0||j>=S.mods.length)return;const p={};S.mods.forEach((m,k)=>p[m.id]={ord:(k+1)*10});const a=S.mods[i].id,b=S.mods[j].id;const tmp=p[a].ord;p[a].ord=p[b].ord;p[b].ord=tmp;await saveState({mods:p})});
ACT['mod-del']=t=>{const m=S.mods.find(x=>x.id===t.dataset.id);confirmBox(m._def?'Restaurar conteúdo original?':'Excluir módulo?',m._def?'Suas edições deste módulo serão descartadas e o texto original volta.':'O módulo criado por você será removido (o progresso dos alunos nele deixa de contar).','mod-del2',{id:m.id},m._def?'Restaurar':'Excluir')};
