ACT['mod-ed']=t=>{const m=S.mods.find(x=>x.id===t.dataset.id);S.ap={edit:m.id,draft:clone({id:m.id,n:m.n,title:m.title,icon:m.icon,intro:m.intro,objectives:m.objectives||[],sections:m.sections||[],examples:m.examples||[],summary:m.summary||[],extras:m.extras||[],cards:m.cards||[]})};S.lock=true;render()};
const ICONS_MOD=['heart','eye','pulse','wind','shield','drop','heartpulse','ruler','flame','bolt','alert','move','book','star'];
function syncMod(){const D=S.ap.draft;if(!D||!$('#me-title'))return;D.title=val('me-title');D.icon=val('me-icon');D.intro=val('me-intro');D.objectives=lines('me-obj');D.summary=lines('me-sum');
 D.sections=D.sections.map((s,i)=>({id:s.id,title:val('ms-t-'+i),body:String(val('ms-b-'+i)).split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean),bullets:lines('ms-l-'+i),callout:val('ms-cx-'+i).trim()?{type:val('ms-ct-'+i)||'info',text:val('ms-cx-'+i).trim()}:undefined}));
 D.examples=D.examples.map((x,i)=>({title:val('mx-t-'+i),env:val('mx-e-'+i),text:val('mx-x-'+i)}));D.extras=D.extras.map((x,i)=>({title:val('mt-t-'+i),text:val('mt-x-'+i)}));
 D.cards=lines('me-cards').map(l=>{const[a,...b]=l.split('|');return{q:a.trim(),a:b.join('|').trim()}}).filter(c=>c.q&&c.a)}
function aModEd(){const D=S.ap.draft;
 return '<div class="row sb"><button class="btn ghost" data-act="med-cancel">'+ic('left')+' Cancelar</button><div class="row"><button class="btn" data-act="med-save">'+ic('save')+' Salvar módulo</button></div></div><h1>'+(D.isNew?'Novo módulo':'Editar módulo')+'</h1>'+
 '<div class="card col">'+fld('Título','me-title',D.title)+'<div class="grid g2"><label class="f">Ícone'+sel('me-icon',ICONS_MOD.map(i=>[i,i]),D.icon)+'</label></div>'+fld('Apresentação (introdução curta)','me-intro',D.intro,{ta:1})+fld('Objetivos de aprendizagem','me-obj',(D.objectives||[]).join('\n'),{ta:1,rows:4,h:'Um objetivo por linha.'})+'</div>'+
 '<h2>Conteúdo em partes</h2>'+D.sections.map((s,i)=>'<div class="card col"><div class="row sb"><b>Parte '+(i+1)+'</b><div class="row"><button class="btn sm sec" data-act="msec-mv" data-i="'+i+'" data-d="-1" '+(i===0?'disabled':'')+'>'+ic('up')+'</button><button class="btn sm sec" data-act="msec-mv" data-i="'+i+'" data-d="1" '+(i===D.sections.length-1?'disabled':'')+'>'+ic('down')+'</button><button class="btn sm danger" data-act="msec-del" data-i="'+i+'">'+ic('trash')+'</button></div></div>'+fld('Título','ms-t-'+i,s.title)+fld('Texto','ms-b-'+i,(s.body||[]).join('\n\n'),{ta:1,rows:6,h:'Separe parágrafos com uma linha em branco.'})+fld('Tópicos (opcional)','ms-l-'+i,(s.bullets||[]).join('\n'),{ta:1,rows:2,h:'Um por linha.'})+'<div class="grid g2"><label class="f">Destaque'+sel('ms-ct-'+i,[['tip','Dica'],['warn','Atenção'],['info','Informação']],s.callout&&s.callout.type||'info')+'</label>'+fld('Texto do destaque (opcional)','ms-cx-'+i,s.callout&&s.callout.text||'')+'</div></div>').join('')+
 '<button class="btn sec" data-act="msec-add">'+ic('plus')+' Adicionar parte</button>'+
 '<h2>Exemplos do dia a dia</h2>'+D.examples.map((x,i)=>'<div class="card col"><div class="row sb"><b>Exemplo '+(i+1)+'</b><button class="btn sm danger" data-act="mx-del" data-i="'+i+'">'+ic('trash')+'</button></div><div class="grid g2">'+fld('Título','mx-t-'+i,x.title)+fld('Ambiente','mx-e-'+i,x.env,{ph:'escola, rua, casa…'})+'</div>'+fld('Situação','mx-x-'+i,x.text,{ta:1})+'</div>').join('')+'<button class="btn sec" data-act="mx-add">'+ic('plus')+' Adicionar exemplo</button>'+
 '<div class="card col">'+fld('Resumo (pontos-chave)','me-sum',(D.summary||[]).join('\n'),{ta:1,rows:5,h:'Um por linha.'})+fld('Cartões de memorização','me-cards',(D.cards||[]).map(c=>c.q+' | '+c.a).join('\n'),{ta:1,rows:5,h:'Formato: termo | definição (um por linha).'})+'</div>'+
 '<h2>Material complementar</h2>'+D.extras.map((x,i)=>'<div class="card col"><div class="row sb"><b>Item '+(i+1)+'</b><button class="btn sm danger" data-act="mt-del" data-i="'+i+'">'+ic('trash')+'</button></div>'+fld('Título','mt-t-'+i,x.title)+fld('Texto','mt-x-'+i,x.text,{ta:1})+'</div>').join('')+'<button class="btn sec" data-act="mt-add">'+ic('plus')+' Adicionar material</button>'+
 '<div class="notice t">'+ic('info')+'<div>As atividades e avaliações deste módulo são editadas na aba <b>Atividades</b>.</div></div><div class="row" style="justify-content:flex-end"><button class="btn" data-act="med-save">'+ic('save')+' Salvar módulo</button></div>'}
const mrr=(k,f)=>{ACT[k]=t=>{syncMod();f(S.ap.draft,t);render()}};
mrr('msec-add',(D)=>D.sections.push({id:D.id+'s'+uid8(),title:'',body:[''],bullets:[]}));mrr('msec-del',(D,t)=>{if(D.sections.length>1)D.sections.splice(+t.dataset.i,1)});mrr('msec-mv',(D,t)=>{const i=+t.dataset.i,j=i+(+t.dataset.d);if(D.sections[j])[D.sections[i],D.sections[j]]=[D.sections[j],D.sections[i]]});
mrr('mx-add',D=>D.examples.push({title:'',env:'',text:''}));mrr('mx-del',(D,t)=>D.examples.splice(+t.dataset.i,1));mrr('mt-add',D=>D.extras.push({title:'',text:''}));mrr('mt-del',(D,t)=>D.extras.splice(+t.dataset.i,1));
ACT['med-cancel']=()=>{S.ap={};S.lock=false;render()};
ACT['med-save']=guard(async()=>{syncMod();const D=S.ap.draft;if(!D.title.trim()){toast('Dê um título ao módulo.','err');return}if(D.sections.some(s=>!s.title||!s.body.length)){toast('Toda parte precisa de título e texto.','err');return}
 const doc=clone(D);delete doc.isNew;doc.sections.forEach(s=>{if(!s.callout)delete s.callout});await DB.set('cmods/'+D.id,doc);if(D.isNew)await saveState({mods:{[D.id]:{st:'draft',ord:(S.mods.length+1)*10}}});S.ap={};S.lock=false;toast('Módulo salvo'+(D.isNew?' como rascunho. Publique quando estiver pronto.':'.'),'ok');render()});

/* ---------- Atividades ---------- */
function resizeImg(file,max){return new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>{const im=new Image();im.onload=()=>{const k=Math.min(1,max/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',.72))};im.onerror=rej;im.src=fr.result};fr.onerror=rej;fr.readAsDataURL(file)})}
function essayQueue(){const out=[];students().forEach(s=>{if(!s.p)return;S.acts.forEach(a=>{const rec=s.p.acts[a.id];if(!rec||!rec.last)return;(a.questions||[]).forEach(q=>{if(q.type!=='essay')return;if(rec.last.r[q.id]!==-1)return;const g=s.g.es&&s.g.es[q.id];out.push({s,a,q,ans:rec.last.ans[q.id],g,at:rec.last.at})})})});return out}
function aActs(){if(S.ap.edit)return aActEd();const tab=S.ap.tab||'list';const eq=essayQueue();const pend=eq.filter(x=>!x.g);
 const tabs='<div class="atabs"><button class="'+(tab==='list'?'on':'')+'" data-act="ago" data-v="acts" data-p=\'{"tab":"list"}\'>Atividades</button><button class="'+(tab==='ess'?'on':'')+'" data-act="ago" data-v="acts" data-p=\'{"tab":"ess"}\'>Correção de discursivas ('+pend.length+')</button><button class="'+(tab==='res'?'on':'')+'" data-act="ago" data-v="acts" data-p=\'{"tab":"res"}\'>Resultados</button></div>';let b='';const st=students();
 if(tab==='list'){b='<div class="row"><button class="btn" data-act="act-new">'+ic('plus')+' Nova atividade</button></div><div class="col">'+S.acts.map(a=>{const m=S.mods.find(x=>x.id===a.mod);const rs=st.map(s=>s.p&&s.p.acts[a.id]).filter(Boolean);const avg=rs.length?Math.round(rs.reduce((x,r)=>x+r.best,0)/rs.length):null;
  return '<div class="card"><div class="row sb"><div><div class="b">'+esc(a.title)+(a._ov?' <span class="chip y">editada</span>':'')+(a._def?'':' <span class="chip t">sua</span>')+'</div><div class="row" style="gap:6px"><span class="chip '+(a.kind==='assessment'?'o':'t')+'">'+(a.kind==='assessment'?'Avaliação':'Fixação')+'</span><span class="chip">'+(a.questions||[]).length+' questões</span><span class="chip">'+(m?'Mód. '+(m.n||m.ord):'sem módulo')+'</span><span class="chip">'+rs.length+' resposta(s)'+(avg!=null?' · média '+avg+'%':'')+'</span>'+(a.counts!==false?'<span class="chip g">conta p/ critério 2</span>':'')+'</div></div><div class="row"><select data-chg="act-st" data-id="'+a.id+'" style="width:auto"><option value="published" '+(a.st==='published'?'selected':'')+'>Publicada</option><option value="draft" '+(a.st!=='published'?'selected':'')+'>Rascunho</option></select><button class="btn sm" data-act="act-ed" data-id="'+a.id+'">'+ic('edit')+' Editar</button>'+((a._ov||!a._def)?'<button class="btn sm danger" data-act="act-del" data-id="'+a.id+'">'+ic('trash')+'</button>':'')+'</div></div></div>'}).join('')+'</div>'}
 else if(tab==='ess'){b=(eq.length?eq.sort((a,b)=>(a.g?1:0)-(b.g?1:0)||b.at-a.at).map(x=>'<div class="card col"><div class="row sb"><b>'+esc(x.s.nick)+'</b><span class="chip '+(x.g?'g':'y')+'">'+(x.g?'Corrigida '+x.g.s+'/'+x.g.m:'Pendente')+'</span></div><div class="xs mut">'+esc(x.a.title)+'</div><div class="b sm">'+esc(x.q.q)+'</div><div class="card flat sm" style="white-space:pre-wrap">'+esc(x.ans||'(em branco)')+'</div><details><summary class="sm">Critérios esperados</summary><p class="sm mut">'+esc(x.q.exp||'')+'</p></details><div class="row"><input type="number" id="eg-s-'+esc(x.q.id)+'-'+esc(x.s.u)+'" min="0" max="10" step="0.5" placeholder="Nota 0–10" value="'+(x.g?x.g.s:'')+'" style="max-width:120px"><input type="text" id="eg-c-'+esc(x.q.id)+'-'+esc(x.s.u)+'" placeholder="Comentário para o aluno" class="grow" value="'+esc(x.g?x.g.c:'')+'"><button class="btn sm" data-act="ess-save" data-u="'+esc(x.s.u)+'" data-q="'+esc(x.q.id)+'">'+ic('check')+' Salvar</button></div></div>').join(''):empty('Nenhuma resposta discursiva enviada ainda.','clip'))}
 else{b='<div class="tbl"><table><thead><tr><th>Estudante</th>'+S.acts.filter(a=>a.st==='published').map(a=>'<th title="'+esc(a.title)+'">'+(S.mods.find(m=>m.id===a.mod)||{n:'?'}).n+(a.kind==='assessment'?'A':'F')+'</th>').join('')+'</tr></thead><tbody>'+st.map(s=>'<tr><td><b>'+esc(s.nick)+'</b></td>'+S.acts.filter(a=>a.st==='published').map(a=>{const r=s.p&&s.p.acts[a.id];return '<td>'+(r?'<button class="btn sm sec" style="padding:2px 6px;min-height:26px" data-act="ans-view" data-u="'+esc(s.u)+'" data-a="'+a.id+'">'+r.best+'%</button>':'—')+'</td>'}).join('')+'</tr>').join('')+'</tbody></table></div><p class="xs mut">F = fixação · A = avaliação · número = módulo. Clique na nota para ver as respostas.</p>'}
 return hdr('Atividades','Crie, edite, publique e corrija.')+tabs+b}
ACT['ess-save']=guard(async t=>{const u=t.dataset.u,q=t.dataset.q;const s=parseFloat(val('eg-s-'+q+'-'+u));if(isNaN(s)||s<0||s>10){toast('Nota entre 0 e 10.','err');return}await DB.upd('grades/'+u,{es:{[q]:{s,m:10,c:val('eg-c-'+q+'-'+u).trim(),at:now(),by:tNick(S.uid)}}});toast('Correção salva.','ok')});
ACT['act-new']=()=>{const id='a_'+uid8();S.ap={edit:id,draft:{id,mod:S.mods[0]&&S.mods[0].id,kind:'activity',title:'',counts:true,questions:[],st:'draft',isNew:1}};S.lock=true;render()};
ACT['act-ed']=t=>{const a=S.acts.find(x=>x.id===t.dataset.id);S.ap={edit:a.id,draft:clone({id:a.id,mod:a.mod,kind:a.kind,title:a.title,counts:a.counts!==false,questions:a.questions,st:a.st})};S.lock=true;render()};
ACT['act-del']=t=>{const a=S.acts.find(x=>x.id===t.dataset.id);confirmBox(a._def?'Restaurar atividade original?':'Excluir atividade?',a._def?'Suas edições serão descartadas.':'A atividade e as respostas associadas deixam de aparecer.','act-del2',{id:a.id},a._def?'Restaurar':'Excluir')};
ACT['act-del2']=guard(async t=>{closeModal();await DB.del('cacts/'+t.dataset.id);toast('Feito.','ok')});
const QT=[['mc','Múltipla escolha'],['tf','Verdadeiro ou falso'],['short','Resposta curta'],['essay','Discursiva'],['match','Associação de colunas'],['seq','Organização de sequência'],['err','Encontre o erro']];
function syncAct(){const D=S.ap.draft;if(!D||!$('#ae-title'))return;D.title=val('ae-title');D.mod=val('ae-mod');D.kind=val('ae-kind');D.counts=$('#ae-counts').checked}
function aActEd(){const D=S.ap.draft;const Q=S.ap.q;
 const qs=D.questions.map((q,i)=>'<div class="card flat"><div class="row sb" style="flex-wrap:nowrap"><div class="grow"><span class="chip t">'+QLBL[q.type]+'</span> <span class="chip">peso '+(q.w||1)+'</span><div class="b sm" style="margin-top:4px">'+esc(q.q)+'</div></div><div class="row" style="gap:4px;flex-wrap:nowrap"><button class="btn sm sec" data-act="aq-mv" data-i="'+i+'" data-d="-1" '+(i===0?'disabled':'')+'>'+ic('up')+'</button><button class="btn sm sec" data-act="aq-mv" data-i="'+i+'" data-d="1" '+(i===D.questions.length-1?'disabled':'')+'>'+ic('down')+'</button><button class="btn sm" data-act="aq-ed" data-i="'+i+'">'+ic('edit')+'</button><button class="btn sm danger" data-act="aq-del" data-i="'+i+'">'+ic('trash')+'</button></div></div></div>').join('');
 return '<div class="row sb"><button class="btn ghost" data-act="aed-cancel">'+ic('left')+' Cancelar</button><div class="row"><button class="btn sec" data-act="aed-save" data-st="draft">'+ic('save')+' Salvar rascunho</button><button class="btn" data-act="aed-save" data-st="published">'+ic('check')+' Publicar</button></div></div><h1>'+(D.isNew?'Nova atividade':'Editar atividade')+'</h1>'+
 '<div class="card col">'+fld('Título','ae-title',D.title)+'<div class="grid g2"><label class="f">Módulo'+sel('ae-mod',S.mods.map(m=>[m.id,(m.n||m.ord)+'. '+m.title]),D.mod)+'</label><label class="f">Tipo'+sel('ae-kind',[['activity','Fixação (feedback imediato)'],['assessment','Avaliação (resultado no final)']],D.kind)+'</label></div><label class="row"><input type="checkbox" id="ae-counts" '+(D.counts!==false?'checked':'')+' style="width:20px;height:20px"><span class="sm">Conta para o critério 2 (aproveitamento de 90% nas avaliações)</span></label></div>'+
 '<div class="row sb"><h2>Questões ('+D.questions.length+')</h2><div class="row"><select id="aq-type" style="width:auto">'+QT.map(([k,n])=>'<option value="'+k+'">'+n+'</option>').join('')+'</select><button class="btn" data-act="aq-new">'+ic('plus')+' Adicionar</button></div></div>'+
 (Q?qForm(Q):'')+'<div class="col">'+(qs||'<div class="card empty">'+ic('clip')+'<p>Nenhuma questão. Escolha um tipo e adicione.</p></div>')+'</div>'}
ACT['aed-cancel']=()=>{S.ap={};S.lock=false;S.qimg=null;render()};
ACT['aed-save']=guard(async t=>{syncAct();const D=S.ap.draft;if(!D.title.trim()){toast('Dê um título.','err');return}if(t.dataset.st==='published'&&!D.questions.length){toast('Adicione ao menos uma questão para publicar.','err');return}
 await DB.set('cacts/'+D.id,{id:D.id,mod:D.mod,kind:D.kind,title:D.title,counts:D.counts,questions:D.questions});await saveState({acts:{[D.id]:{st:t.dataset.st}}});S.ap={};S.lock=false;toast(t.dataset.st==='published'?'Atividade publicada.':'Rascunho salvo.','ok');render()});
ACT['aq-mv']=t=>{syncAct();const D=S.ap.draft,i=+t.dataset.i,j=i+(+t.dataset.d);if(D.questions[j])[D.questions[i],D.questions[j]]=[D.questions[j],D.questions[i]];render()};
ACT['aq-del']=t=>{syncAct();S.ap.draft.questions.splice(+t.dataset.i,1);render()};
ACT['aq-new']=()=>{syncAct();S.qimg=null;S.ap.q={idx:-1,q:{id:'q_'+uid8(),type:val('aq-type'),q:'',exp:'',w:1}};render()};
ACT['aq-ed']=t=>{syncAct();const i=+t.dataset.i;S.qimg=null;S.ap.q={idx:i,q:clone(S.ap.draft.questions[i])};render()};
