function qForm(Q){const q=Q.q,t=q.type;let b='';
 if(t==='mc'){const o=q.options||['','','',''];b='<div class="b sm">Alternativas <span class="mut">(marque a correta)</span></div>'+[0,1,2,3,4].map(i=>'<div class="row" style="flex-wrap:nowrap"><input type="radio" name="qe-ans" value="'+i+'" '+((q.answer||0)===i?'checked':'')+' style="width:22px;height:22px"><input type="text" id="qe-o'+i+'" value="'+esc(o[i]||'')+'" placeholder="Alternativa '+(i+1)+(i>=2?' (opcional)':'')+'"></div>').join('')}
 else if(t==='tf')b='<label class="f">Resposta correta'+sel('qe-tf',[['true','Verdadeiro'],['false','Falso']],String(q.answer!==false))+'</label>';
 else if(t==='short')b=fld('Respostas aceitas','qe-sh',(q.answers||[]).join('\n'),{ta:1,rows:3,h:'Uma por linha, em minúsculas e sem acento. A resposta do aluno é aceita se contiver algum desses trechos.'});
 else if(t==='essay')b='<div class="notice t">'+ic('info')+'<div>Discursivas ficam para correção manual. Use o campo de explicação para os critérios esperados.</div></div>';
 else if(t==='match')b=fld('Pares','qe-mt',(q.pairs||[]).map(p=>p[0]+' | '+p[1]).join('\n'),{ta:1,rows:5,h:'Formato: item | correspondência (3 a 5 linhas).'});
 else if(t==='seq')b=fld('Itens na ordem correta','qe-sq',(q.items||[]).join('\n'),{ta:1,rows:5,h:'Um por linha (4 a 6). O aluno vê embaralhado.'});
 else if(t==='err'){const it=q.items||['','','',''];b='<div class="b sm">Afirmações <span class="mut">(marque a ERRADA)</span></div>'+[0,1,2,3].map(i=>'<div class="row" style="flex-wrap:nowrap"><input type="radio" name="qe-ans" value="'+i+'" '+((q.answer||0)===i?'checked':'')+' style="width:22px;height:22px"><input type="text" id="qe-o'+i+'" value="'+esc(it[i]||'')+'" placeholder="Afirmação '+(i+1)+'"></div>').join('')}
 const img=S.qimg||q.img;
 return '<div class="card col" style="border:2px solid var(--blue)"><div class="row sb"><b>'+(Q.idx<0?'Nova':'Editar')+' questão · '+QLBL[t]+'</b></div>'+fld('Enunciado','qe-q',q.q,{ta:1})+b+fld('Explicação / feedback','qe-exp',q.exp||'',{ta:1,rows:2})+'<div class="grid g2">'+fld('Pontuação (peso)','qe-w',q.w||1,{type:'number',min:1,max:10})+'<label class="f">Imagem (opcional)<input type="file" accept="image/*" id="qe-file"></label></div><div id="qe-prev">'+(img?'<img src="'+img+'" alt="Pré-visualização" style="max-height:140px;border-radius:10px">':'')+'</div>'+(img?'<button class="btn sm sec" data-act="qe-noimg">Remover imagem</button>':'')+'<div class="row" style="justify-content:flex-end"><button class="btn sec" data-act="aq-cancel">Cancelar</button><button class="btn" data-act="aq-save">'+ic('check')+' Salvar questão</button></div></div>'}
