 if(!q.q){toast('Escreva o enunciado.','err');return}if(!q.exp){toast('Escreva uma explicação.','err');return}
 if(t==='mc'){const o=[0,1,2,3,4].map(i=>val('qe-o'+i).trim());const r=document.querySelector('input[name=qe-ans]:checked');const idx=r?+r.value:0;if(!o[idx]){toast('A alternativa correta não pode estar vazia.','err');return}const opts=[],map={};o.forEach((x,i)=>{if(x){map[i]=opts.length;opts.push(x)}});if(opts.length<2){toast('Informe ao menos 2 alternativas.','err');return}q.options=opts;q.answer=map[idx]}
 else if(t==='tf')q.answer=val('qe-tf')==='true';
